package api

import (
	"context"
	"encoding/json"
	"net/http"
)

// Image fields in public payloads that may have WebP variants generated by the image pipeline (PRD §76).
var imageKeys = map[string]bool{"artwork_url": true, "podcast_artwork_url": true, "banner_url": true, "cover_url": true, "photo_url": true}

func collectImageURLs(v any, out map[string]bool) {
	switch x := v.(type) {
	case map[string]any:
		for k, val := range x {
			if s, ok := val.(string); ok && imageKeys[k] && s != "" {
				out[s] = true
			} else {
				collectImageURLs(val, out)
			}
		}
	case []any:
		for _, it := range x {
			collectImageURLs(it, out)
		}
	}
}

// imageVariants maps original image URLs to their processed variants {thumbnail, small, medium, large, original}.
func (s *Server) imageVariants(ctx context.Context, urls []string) map[string]map[string]string {
	out := map[string]map[string]string{}
	if len(urls) == 0 {
		return out
	}
	rows, err := s.App.DB.Query(ctx, `SELECT DISTINCT ON (variants->>'original') variants FROM images
		WHERE status='READY' AND variants->>'original' = ANY($1) ORDER BY variants->>'original', id DESC`, urls)
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var v map[string]string
		if rows.Scan(&v) == nil && len(v) > 1 {
			out[v["original"]] = v
		}
	}
	return out
}

// writePublic writes a public envelope and adds `image_variants` so the web app can serve
// responsive WebP images (srcset) while feeds keep the original JPEG/PNG artwork.
func (s *Server) writePublic(w http.ResponseWriter, r *http.Request, envelope map[string]any) {
	raw, err := json.Marshal(envelope)
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	var generic any
	json.Unmarshal(raw, &generic)
	set := map[string]bool{}
	collectImageURLs(generic, set)
	urls := make([]string, 0, len(set))
	for u := range set {
		urls = append(urls, u)
	}
	envelope["image_variants"] = s.imageVariants(r.Context(), urls)
	writeJSON(w, http.StatusOK, envelope)
}

func (s *Server) writePublicData(w http.ResponseWriter, r *http.Request, data any) {
	s.writePublic(w, r, map[string]any{"data": data})
}

func (s *Server) writePublicList(w http.ResponseWriter, r *http.Request, items any, total, page, per int) {
	s.writePublic(w, r, map[string]any{"data": items, "meta": map[string]int{
		"total": total, "page": page, "per_page": per, "pages": (total + per - 1) / max(per, 1)}})
}
